import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as e,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Gemini Canvas","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/canvas.md","filePath":"zh/products/ai-coding/gemini/canvas.md","lastUpdated":1787048027000}'),i={name:"zh/products/ai-coding/gemini/canvas.md"};function o(r,a,l,p,d,h){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="gemini-canvas" tabindex="-1">Gemini Canvas <a class="header-anchor" href="#gemini-canvas" aria-label="Permalink to &quot;Gemini Canvas&quot;">​</a></h1><blockquote><p>Gemini 应用内的动态工作区。价值在于<strong>跳过工程搭建直接看到能点的东西</strong>。</p></blockquote><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><p>普通对话里 AI 只能给你一段代码，你要自己建工程、装依赖、跑起来才能看到效果。Canvas 把这段路砍掉了——它在对话旁边给你一个工作区，产出的东西可以直接交互。</p><p><strong>它的定位是原型，不是生产代码来源。</strong> 想清楚这一点，后面所有取舍都很自然。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><p>官方页面把 Canvas 描述为可以与 Gemini 协作创建和精修文档、代码与网页设计的交互式空间，能够实时预览产出。</p><p>对开发者最有意义的两点：</p><p><strong>看得见的迭代</strong>：产出不是静态代码块，你能直接操作它，然后基于&quot;我看到的效果&quot;提下一轮要求，而不是基于&quot;我读代码想象的效果&quot;。</p><p><strong>局部精修</strong>：可以针对某一部分提要求，不必每次重新生成整份文件。这在调 UI 细节时省下大量时间。</p><h2 id="分层推进" tabindex="-1">分层推进 <a class="header-anchor" href="#分层推进" aria-label="Permalink to &quot;分层推进&quot;">​</a></h2><p>这是用 Canvas 唯一重要的方法论。</p><p><strong>反模式</strong>：一次性要求生成带完整业务逻辑的全尺寸应用。</p><p>问题不在于它做不到，而在于<strong>你失去了&quot;哪一步开始错的&quot;这个信息</strong>。一次生成两百行，出问题你只能整个重来。</p><p><strong>做法</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一层：DOM 结构 + 基础交互      → 确认逻辑没跑偏</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>第二层：套设计系统（Tailwind / CSS 变量）  → 保持代码整洁</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>第三层：搬进正式工程做类型和测试   → 这一步离开 Canvas</span></span></code></pre></div><p>每层结束都确认一次。<strong>第三层意味着退出 Canvas</strong>——不要试图在里面完成工程化，那不是它的强项。</p><h3 id="提示词示例" tabindex="-1">提示词示例 <a class="header-anchor" href="#提示词示例" aria-label="Permalink to &quot;提示词示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据以下 JSON 结构，构建一个包含实时收入折线图和客户流失率饼图的业务看板：</span></span>
<span class="line"><span>- 支持暗黑模式切换</span></span>
<span class="line"><span>- 响应式布局</span></span>
<span class="line"><span>- 先只做结构和交互，样式后面再说</span></span></code></pre></div><p>最后一句是关键——它把这一轮限制在第一层。</p><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th style="text-align:center;">适合度</th><th>说明</th></tr></thead><tbody><tr><td>一次性原型</td><td style="text-align:center;">高</td><td>验证想法的最快路径，不用投工程资源</td></tr><tr><td>给非技术同事做小工具</td><td style="text-align:center;">高</td><td>对方看得懂能点的东西，看不懂代码</td></tr><tr><td>独立轻量微应用</td><td style="text-align:center;">中</td><td>能做，但迁出去仍需工程化</td></tr><tr><td>生产级应用</td><td style="text-align:center;">低</td><td>容错要求高的系统不要从这里起步</td></tr></tbody></table><h2 id="与其他产品怎么选" tabindex="-1">与其他产品怎么选 <a class="header-anchor" href="#与其他产品怎么选" aria-label="Permalink to &quot;与其他产品怎么选&quot;">​</a></h2><p>Canvas 不在工程化主线上，它和其他产品不是竞争关系：</p><ul><li>想要<strong>能提交进仓库</strong>的代码 → <a href="./gemini-cli.html">Gemini CLI</a> 或 <a href="./antigravity.html">Antigravity</a></li><li>想要<strong>先看到效果再决定要不要做</strong> → Canvas</li><li>想要<strong>落地页 / 宣传片 / 产品演示视频</strong> → <a href="./flow.html">Google Flow</a></li></ul><p>很实用的组合是：用 Canvas 试三个方向、挑一个，再让 Antigravity 在真实工程里实现它。对外讲这个功能时，再用 Flow 出成片。</p><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://gemini.google/overview/canvas/" target="_blank" rel="noreferrer">Canvas 概览</a></li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./gemini-cookbook.html#_13-快速做个能点的原型">Cookbook</a> — 原型配方</li><li><a href="./gemini-cheatsheet.html#按任务选">速查表</a> — 按任务选工具</li></ul>`,30)])])}const v=t(i,[["render",o]]);export{b as __pageData,v as default};
